using System;using System.Collections.Generic;using System.Linq;using LocalGame.Data;
namespace CashflowChains.Domain {
 public sealed class CityCollection {public readonly string Id,Name;public readonly string[] Pieces;public CityCollection(string id,string name,params string[] pieces){Id=id;Name=name;Pieces=pieces;}}
 public static class CityCollections {
  public static readonly CityCollection[] All={new CityCollection("first-street","FIRST STREET","home","cafe","farm","warehouse"),new CityCollection("daily-life","DAILY LIFE","grocer","market","diner","park"),new CityCollection("working-city","WORKING CITY","power","factory","office","bank"),new CityCollection("bright-lights","BRIGHT LIGHTS","apartment","boutique","shopping_mall","hotel"),new CityCollection("harbor-life","HARBOR LIFE","logistics","port","freight_yard","stadium"),new CityCollection("tomorrow","TOMORROW","tech_office","recycler","solar_array","landmark"),new CityCollection("culture","CULTURE CIRCUIT","bakery","cinema","university","tram"),new CityCollection("smart-city","SMART CITY","battery","greenhouse","data_center","exchange")};
  public static HashSet<int> Contributors(Board b,RoundResult r){var ids=new HashSet<int>(r.Events.Where(e=>e.Reason=="sale"&&e.Credits>0).Select(e=>e.Source));for(int pass=0;pass<b.Nodes.Count;pass++){int before=ids.Count;foreach(var e in r.Events.Where(e=>e.Reason=="shipment"&&e.Count>0))if(ids.Contains(e.Target))ids.Add(e.Source);if(before==ids.Count)break;}
   foreach(var n in b.Nodes){if(n.Kind=="landmark"&&r.Events.Any(e=>e.Reason=="diversity")){ids.Add(n.Id);continue;}if(n.Kind!="park"&&n.Kind!="bank"&&n.Kind!="office"&&n.Kind!="tech_office")continue;var nearby=b.Nodes.Where(v=>Math.Abs(v.X-n.X)+Math.Abs(v.Y-n.Y)==1&&ids.Contains(v.Id)).ToArray();if(n.Kind=="bank"){var first=b.Nodes.Where(v=>Math.Abs(v.X-n.X)+Math.Abs(v.Y-n.Y)==1&&Pieces.Get(v.Kind).Credits>0).OrderBy(v=>v.Id).FirstOrDefault();if(first!=null&&ids.Contains(first.Id))ids.Add(n.Id);}else if(nearby.Any(v=>n.Kind=="park"?v.Kind=="home"||v.Kind=="apartment"||v.Kind=="cafe":Pieces.Get(v.Kind).Credits>0))ids.Add(n.Id);}
   return ids;
  }
  public static void Record(Profile profile,Board board,RoundResult result){var used=Contributors(board,result);foreach(var n in board.Nodes.Where(n=>used.Contains(n.Id)))if(!profile.Collection.Contains(n.Kind))profile.Collection.Add(n.Kind);foreach(var combo in ComboBook.Evaluate(board,result))if(!profile.DiscoveredCombos.Contains(combo))profile.DiscoveredCombos.Add(combo);}
  public static bool Complete(Profile p,CityCollection set)=>set.Pieces.All(p.Collection.Contains);
  public static bool Claim(Profile p,string id){var set=All.FirstOrDefault(s=>s.Id==id);return set!=null&&Complete(p,set)&&p.Grant("collection-"+id,200);}
 }
 public sealed class ComboDefinition {public readonly string Name,Rule;public ComboDefinition(string name,string rule){Name=name;Rule=rule;}}
 public static class ComboBook {
  public static readonly ComboDefinition[] All={
   new ComboDefinition("Morning rush","Sell six cafe orders supplied by real customers and goods."),new ComboDefinition("Local loop","Sell with three distinct shop types in one chain."),new ComboDefinition("City symphony","A landmark rewards three profitable business types."),new ComboDefinition("Financial district","An eligible bank boosts at least three real sales."),new ComboDefinition("Factory town","Factory goods reach two different profitable outlets."),new ComboDefinition("Long distance","Logistics delivers across one empty plot."),new ComboDefinition("Luxury row","A profitable boutique uses a bank and a contributing park."),new ComboDefinition("Supply master","One depot or freight yard supplies three profitable outlets."),
   new ComboDefinition("Full house","Apartment customers contribute to ten sales."),new ComboDefinition("Clean power","Solar energy contributes to profitable production."),new ComboDefinition("Night shift","Complete six diner orders."),new ComboDefinition("Cargo circuit","Imported goods contribute to a profitable outlet."),new ComboDefinition("Culture circuit","Tram passengers reach a profitable cinema."),new ComboDefinition("Smart supply","Greenhouse or data-center goods reach two profitable outlets."),new ComboDefinition("Campus circuit","University passengers contribute to a real sale."),new ComboDefinition("Market makers","An exchange completes three orders using all three resources.")
  };
  public static string[] Evaluate(Board b,RoundResult r){var names=new List<string>();var sales=r.Events.Where(e=>e.Reason=="sale"&&e.Credits>0).ToArray();var used=CityCollections.Contributors(b,r);Func<int,string> kind=id=>b.Nodes.First(n=>n.Id==id).Kind;var sinks=new HashSet<int>(sales.Select(e=>e.Source));
   Func<Node,int> reaches=n=>{var seen=new HashSet<int>{n.Id};for(int i=0;i<b.Nodes.Count;i++)foreach(var e in r.Events.Where(e=>e.Reason=="shipment"&&e.Count>0))if(seen.Contains(e.Source))seen.Add(e.Target);return sinks.Count(id=>seen.Contains(id));};
   Func<string,bool> contributed=k=>b.Nodes.Any(n=>n.Kind==k&&used.Contains(n.Id));Action<bool,string> add=(yes,name)=>{if(yes)names.Add(name);};
   add(sales.Where(e=>kind(e.Source)=="cafe").Sum(e=>e.Count)>=6,"Morning rush");add(sales.Select(e=>kind(e.Source)).Distinct().Count()>=3,"Local loop");add(r.Events.Any(e=>e.Reason=="diversity"),"City symphony");
   add(b.Nodes.Where(n=>n.Kind=="bank"&&used.Contains(n.Id)).Any(bank=>{var outlet=b.Nodes.Where(n=>Pieces.Get(n.Kind).Credits>0&&Math.Abs(n.X-bank.X)+Math.Abs(n.Y-bank.Y)==1).OrderBy(n=>n.Id).FirstOrDefault();return outlet!=null&&sales.Count(e=>e.Source==outlet.Id)>=3;}),"Financial district");
   add(b.Nodes.Any(n=>n.Kind=="factory"&&reaches(n)>=2),"Factory town");add(r.Events.Any(e=>e.Reason=="shipment"&&kind(e.Source)=="logistics"&&b.Nodes.Any(a=>a.Id==e.Source&&b.Nodes.Any(z=>z.Id==e.Target&&Math.Abs(a.X-z.X)+Math.Abs(a.Y-z.Y)==2))),"Long distance");
   add(sales.Any(e=>kind(e.Source)=="boutique")&&contributed("park")&&contributed("bank"),"Luxury row");add(b.Nodes.Any(n=>(n.Kind=="warehouse"||n.Kind=="freight_yard")&&reaches(n)>=3),"Supply master");
   add(contributed("apartment")&&sales.Sum(e=>e.Count)>=10,"Full house");add(contributed("solar_array"),"Clean power");add(sales.Where(e=>kind(e.Source)=="diner").Sum(e=>e.Count)>=6,"Night shift");add(contributed("port"),"Cargo circuit");add(contributed("tram")&&sales.Any(e=>kind(e.Source)=="cinema"),"Culture circuit");add(b.Nodes.Any(n=>(n.Kind=="greenhouse"||n.Kind=="data_center")&&reaches(n)>=2),"Smart supply");add(contributed("university"),"Campus circuit");add(sales.Where(e=>kind(e.Source)=="exchange").Sum(e=>e.Count)>=3,"Market makers");return names.ToArray();
  }
 }
}
